import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { handler as authHandler } from '../lib/handlers/auth';

describe('Auth Registration & Password Reset Unit Tests', () => {
  test('POST /auth/register throws ValidationError when password is missing', async () => {
    process.env.MAIN_TABLE_NAME = 'CrossboxGymMainTable';
    process.env.USER_POOL_ID = 'mock_pool_id';
    process.env.USER_POOL_CLIENT_ID = 'mock_client_id';
    process.env.FRONTEND_URL = 'https://localhost';

    const event: any = {
      requestContext: {
        http: {
          method: 'POST',
          path: '/auth/register',
        },
      },
      body: JSON.stringify({ email: 'test@example.com' }),
      isBase64Encoded: false,
    };

    const response: any = await authHandler(event);
    assert.equal(response.statusCode, 400);
    const body = JSON.parse(response.body);
    assert.equal(body.error || body.message, 'Email and password are required');
  });

  test('POST /auth/forgot-password throws ValidationError when email is missing', async () => {
    process.env.MAIN_TABLE_NAME = 'CrossboxGymMainTable';
    process.env.USER_POOL_ID = 'mock_pool_id';
    process.env.USER_POOL_CLIENT_ID = 'mock_client_id';
    process.env.FRONTEND_URL = 'https://localhost';

    const event: any = {
      requestContext: {
        http: {
          method: 'POST',
          path: '/auth/forgot-password',
        },
      },
      body: JSON.stringify({}),
      isBase64Encoded: false,
    };

    const response: any = await authHandler(event);
    assert.equal(response.statusCode, 400);
    const body = JSON.parse(response.body);
    assert.equal(body.error || body.message, 'Email is required');
  });

  test('POST /auth/confirm-forgot-password throws ValidationError when missing parameters', async () => {
    process.env.MAIN_TABLE_NAME = 'CrossboxGymMainTable';
    process.env.USER_POOL_ID = 'mock_pool_id';
    process.env.USER_POOL_CLIENT_ID = 'mock_client_id';
    process.env.FRONTEND_URL = 'https://localhost';

    const event: any = {
      requestContext: {
        http: {
          method: 'POST',
          path: '/auth/confirm-forgot-password',
        },
      },
      body: JSON.stringify({ email: 'test@example.com' }),
      isBase64Encoded: false,
    };

    const response: any = await authHandler(event);
    assert.equal(response.statusCode, 400);
    const body = JSON.parse(response.body);
    assert.equal(body.error || body.message, 'Email, confirmation code, and newPassword are required');
  });
});

import { APIGatewayProxyEventV2 } from 'aws-lambda';
import {
  CognitoIdentityProviderClient,
  AdminInitiateAuthCommand,
  AdminCreateUserCommand,
  AdminSetUserPasswordCommand,
  AdminGetUserCommand,
  AdminResetUserPasswordCommand,
  ForgotPasswordCommand,
  ConfirmForgotPasswordCommand,
} from '@aws-sdk/client-cognito-identity-provider';
import { PutCommand, GetCommand, UpdateCommand } from '@aws-sdk/lib-dynamodb';
import { randomBytes, createHash } from 'crypto';
import {
  withHandler,
  parseJsonBody,
  extractJwtClaims,
  HttpError,
  ValidationError,
  NotFoundError,
  UnauthorizedError,
} from '../shared/http';
import { ddb } from '../shared/database';
import { MagicLinkToken, MagicLinkRateLimit } from '../shared/types';
import { getMainTableName, getFrontendUrl, getUserPoolId, getUserPoolClientId } from '../shared/config';

const cognito = new CognitoIdentityProviderClient({});

export const handler = withHandler(async (event: APIGatewayProxyEventV2) => {
  const method = event.requestContext.http.method;
  const path = event.requestContext.http.path;
  const userPoolId = getUserPoolId();
  const clientId = getUserPoolClientId();

  if (method === 'POST' && path === '/auth/login') {
    const { email, password } = parseJsonBody(event);
    if (!email || !password) {
      throw new ValidationError('Email and password are required');
    }

    try {
      const authRes = await cognito.send(
        new AdminInitiateAuthCommand({
          UserPoolId: userPoolId,
          ClientId: clientId,
          AuthFlow: 'ADMIN_USER_PASSWORD_AUTH',
          AuthParameters: {
            USERNAME: email,
            PASSWORD: password,
          },
        })
      );

      if (authRes.ChallengeName === 'NEW_PASSWORD_REQUIRED') {
        throw new UnauthorizedError(
          'Your account requires password setup. Please use the Magic Link or Password Reset flow to set your permanent password.'
        );
      }

      const authResult = authRes.AuthenticationResult;
      if (!authResult) {
        throw new UnauthorizedError('Invalid email or password');
      }

      return {
        accessToken: authResult.AccessToken,
        idToken: authResult.IdToken,
        refreshToken: authResult.RefreshToken,
        expiresIn: authResult.ExpiresIn,
      };
    } catch (err: any) {
      if (err instanceof HttpError) {
        throw err;
      }
      if (
        err.name === 'PasswordResetRequiredException' ||
        err.name === 'UserPasswordNotVerifiedException' ||
        err.message?.includes('NEW_PASSWORD_REQUIRED')
      ) {
        throw new UnauthorizedError(
          'Your account requires password setup. Please use the Magic Link or Password Reset flow to set your permanent password.'
        );
      }
      console.error('Login error:', err);
      throw new UnauthorizedError(err.message || 'Invalid email or password');
    }
  }

  if (method === 'POST' && path === '/auth/magic-link') {
    const { email } = parseJsonBody(event);
    if (!email) {
      throw new ValidationError('Email is required');
    }

    const now = Math.floor(Date.now() / 1000);
    const rateLimitKey = `RATELIMIT#${email}`;

    // Check rate limiting
    const rlRes = await ddb.send(
      new GetCommand({
        TableName: getMainTableName(),
        Key: { PK: rateLimitKey, SK: 'RATELIMIT' },
      })
    );
    const rateLimit = rlRes.Item as MagicLinkRateLimit | undefined;

    if (rateLimit && rateLimit.request_count >= 5 && now - new Date(rateLimit.window_start).getTime() / 1000 < 3600) {
      throw new ValidationError('Magic link request limit reached. Please try again in an hour.');
    }

    // Update rate limit
    await ddb.send(
      new PutCommand({
        TableName: getMainTableName(),
        Item: {
          PK: rateLimitKey,
          SK: 'RATELIMIT',
          request_count: (rateLimit?.request_count || 0) + 1,
          window_start: rateLimit?.window_start || new Date().toISOString(),
          ttl: now + 3600,
        },
      })
    );

    // Generate token
    const token = randomBytes(32).toString('hex');
    const tokenHash = createHash('sha256').update(token).digest('hex');

    await ddb.send(
      new PutCommand({
        TableName: getMainTableName(),
        Item: {
          PK: `TOKEN#${tokenHash}`,
          SK: 'TOKEN',
          user_id: email,
          created_at: new Date().toISOString(),
          ttl: now + 15 * 60, // 15 minutes TTL
        } as MagicLinkToken,
      })
    );

    const magicUrl = `${getFrontendUrl()}/auth/magic-link/verify?token=${token}&email=${encodeURIComponent(email)}`;

    return { message: 'Magic link generated successfully', magicUrl };
  }

  if (method === 'GET' && path === '/auth/magic-link/verify') {
    const query = event.queryStringParameters || {};
    const token = query.token;
    const email = query.email;

    if (!token || !email) {
      throw new ValidationError('Token and email query parameters are required');
    }

    const tokenHash = createHash('sha256').update(token).digest('hex');
    const tokenRes = await ddb.send(
      new GetCommand({
        TableName: getMainTableName(),
        Key: { PK: `TOKEN#${tokenHash}`, SK: 'TOKEN' },
      })
    );

    const tokenItem = tokenRes.Item as MagicLinkToken | undefined;
    if (!tokenItem || tokenItem.user_id !== email) {
      throw new ValidationError('Invalid or expired magic link token');
    }

    return {
      verified: true,
      email,
      message: 'Magic link verified successfully',
    };
  }

  if (method === 'POST' && path === '/auth/set-password') {
    const claims = extractJwtClaims(event);
    if (!claims) throw new UnauthorizedError('Unauthorized');

    const email = claims.email as string;
    const { newPassword } = parseJsonBody(event);
    if (!newPassword || newPassword.length < 8) {
      throw new ValidationError('Password must be at least 8 characters long');
    }

    try {
      await cognito.send(
        new AdminSetUserPasswordCommand({
          UserPoolId: userPoolId,
          Username: email,
          Password: newPassword,
          Permanent: true,
        })
      );
    } catch (e: any) {
      if (e instanceof HttpError) throw e;
      throw new ValidationError(e.message || 'Failed to update password');
    }

    await ddb.send(
      new UpdateCommand({
        TableName: getMainTableName(),
        Key: { PK: `USER#${claims.sub}`, SK: 'PROFILE' },
        UpdateExpression: 'SET password_set = :true',
        ExpressionAttributeValues: { ':true': true },
      })
    );

    return { message: 'Password updated successfully' };
  }

  if (method === 'POST' && path === '/auth/forgot-password') {
    const { email } = parseJsonBody(event);
    if (!email) {
      throw new ValidationError('Email is required');
    }

    try {
      await cognito.send(
        new ForgotPasswordCommand({
          ClientId: clientId,
          Username: email,
        })
      );
    } catch (e: any) {
      await cognito
        .send(
          new AdminResetUserPasswordCommand({
            UserPoolId: userPoolId,
            Username: email,
          })
        )
        .catch(() => {});
    }

    return {
      message: `Password reset request initiated for ${email}`,
      email,
    };
  }

  if (method === 'POST' && path === '/auth/confirm-forgot-password') {
    const { email, code, newPassword } = parseJsonBody(event);
    if (!email || !code || !newPassword) {
      throw new ValidationError('Email, confirmation code, and newPassword are required');
    }
    if (newPassword.length < 8) {
      throw new ValidationError('Password must be at least 8 characters long');
    }

    try {
      await cognito.send(
        new ConfirmForgotPasswordCommand({
          ClientId: clientId,
          Username: email,
          ConfirmationCode: code,
          Password: newPassword,
        })
      );
    } catch (e: any) {
      if (e instanceof HttpError) throw e;
      throw new ValidationError(e.message || 'Confirmation failed');
    }

    const userRes = await cognito
      .send(
        new AdminGetUserCommand({
          UserPoolId: userPoolId,
          Username: email,
        })
      )
      .catch(() => null);
    const sub = userRes?.UserAttributes?.find((a) => a.Name === 'sub')?.Value;

    if (sub) {
      await ddb
        .send(
          new UpdateCommand({
            TableName: getMainTableName(),
            Key: { PK: `USER#${sub}`, SK: 'PROFILE' },
            UpdateExpression: 'SET password_set = :true',
            ExpressionAttributeValues: { ':true': true },
          })
        )
        .catch(() => {});
    }

    return { message: 'Password reset confirmed successfully' };
  }

  if (method === 'POST' && path === '/auth/reset-password') {
    const { email, token, newPassword } = parseJsonBody(event);
    if (!email || !newPassword) {
      throw new ValidationError('Email and newPassword are required');
    }
    if (newPassword.length < 8) {
      throw new ValidationError('Password must be at least 8 characters long');
    }

    if (token) {
      const tokenHash = createHash('sha256').update(token).digest('hex');
      const tokenRes = await ddb.send(
        new GetCommand({
          TableName: getMainTableName(),
          Key: { PK: `TOKEN#${tokenHash}`, SK: 'TOKEN' },
        })
      );

      const tokenItem = tokenRes.Item as MagicLinkToken | undefined;
      if (!tokenItem || tokenItem.user_id !== email) {
        throw new ValidationError('Invalid or expired reset token');
      }
    }

    try {
      await cognito.send(
        new AdminSetUserPasswordCommand({
          UserPoolId: userPoolId,
          Username: email,
          Password: newPassword,
          Permanent: true,
        })
      );
    } catch (e: any) {
      if (e instanceof HttpError) throw e;
      throw new ValidationError(e.message || 'Failed to reset password');
    }

    const userRes = await cognito
      .send(
        new AdminGetUserCommand({
          UserPoolId: userPoolId,
          Username: email,
        })
      )
      .catch(() => null);
    const sub = userRes?.UserAttributes?.find((a) => a.Name === 'sub')?.Value;

    if (sub) {
      await ddb
        .send(
          new UpdateCommand({
            TableName: getMainTableName(),
            Key: { PK: `USER#${sub}`, SK: 'PROFILE' },
            UpdateExpression: 'SET password_set = :true',
            ExpressionAttributeValues: { ':true': true },
          })
        )
        .catch(() => {});
    }

    return { message: 'Password reset successfully' };
  }

  if (method === 'POST' && path === '/auth/register') {
    const { email, password } = parseJsonBody(event);
    if (!email || !password) {
      throw new ValidationError('Email and password are required');
    }

    let sub = '';
    try {
      const userRes = await cognito.send(
        new AdminCreateUserCommand({
          UserPoolId: userPoolId,
          Username: email,
          UserAttributes: [
            { Name: 'email', Value: email },
            { Name: 'email_verified', Value: 'true' },
          ],
          MessageAction: 'SUPPRESS',
        })
      );
      sub = userRes.User?.Attributes?.find((a) => a.Name === 'sub')?.Value || '';

      await cognito.send(
        new AdminSetUserPasswordCommand({
          UserPoolId: userPoolId,
          Username: email,
          Password: password,
          Permanent: true,
        })
      );
    } catch (e: any) {
      if (e instanceof HttpError) throw e;
      if (e.name === 'UsernameExistsException') {
        throw new ValidationError('An account with this email address already exists.');
      }
      if (e.name === 'InvalidPasswordException') {
        throw new ValidationError(
          e.message || 'Password does not conform to security policy (must contain uppercase letters and numbers).'
        );
      }
      if (e.name === 'InvalidParameterException') {
        throw new ValidationError(e.message || 'Invalid parameters provided.');
      }
      console.error('Registration error:', e);
      throw new ValidationError(e.message || 'Registration failed.');
    }

    if (sub) {
      await ddb.send(
        new PutCommand({
          TableName: getMainTableName(),
          Item: {
            PK: `USER#${sub}`,
            SK: 'PROFILE',
            email,
            role: 'member',
            password_set: true,
            created_at: new Date().toISOString(),
          },
        })
      );
    }

    return {
      message: `User ${email} registered successfully`,
      email,
      sub,
    };
  }

  throw new NotFoundError('Route not found');
});

import { APIGatewayProxyEventV2, APIGatewayProxyResultV2 } from 'aws-lambda';

export class HttpError extends Error {
  constructor(
    public statusCode: number,
    message: string
  ) {
    super(message);
    this.name = 'HttpError';
  }
}

export class BadRequestError extends HttpError {
  constructor(message = 'Bad Request') {
    super(400, message);
    this.name = 'BadRequestError';
  }
}

export class ValidationError extends HttpError {
  constructor(message = 'Validation Error') {
    super(400, message);
    this.name = 'ValidationError';
  }
}

export class UnauthorizedError extends HttpError {
  constructor(message = 'Unauthorized') {
    super(401, message);
    this.name = 'UnauthorizedError';
  }
}

export class ForbiddenError extends HttpError {
  constructor(message = 'Forbidden') {
    super(403, message);
    this.name = 'ForbiddenError';
  }
}

export class NotFoundError extends HttpError {
  constructor(message = 'Not Found') {
    super(404, message);
    this.name = 'NotFoundError';
  }
}

export class ConflictError extends HttpError {
  constructor(message = 'Conflict') {
    super(409, message);
    this.name = 'ConflictError';
  }
}

const COMMON_HEADERS = {
  'Content-Type': 'application/json',
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'Content-Type,Authorization,X-Amz-Date,X-Api-Key,X-Amz-Security-Token',
  'Access-Control-Allow-Methods': 'GET,POST,PUT,DELETE,OPTIONS',
  'Access-Control-Allow-Credentials': 'true',
  Vary: 'Origin',
};

export function withHandler(handler: (event: APIGatewayProxyEventV2) => Promise<any>) {
  return async (event: APIGatewayProxyEventV2): Promise<APIGatewayProxyResultV2> => {
    // Handle CORS preflight OPTIONS request
    const method = event.requestContext?.http?.method || (event as any).httpMethod;
    if (method === 'OPTIONS') {
      return {
        statusCode: 200,
        headers: COMMON_HEADERS,
        body: '',
      };
    }

    try {
      const result = await handler(event);
      if (result && typeof result === 'object' && 'statusCode' in result) {
        return {
          ...result,
          headers: {
            ...COMMON_HEADERS,
            ...(result.headers || {}),
          },
        };
      }
      return {
        statusCode: 200,
        headers: COMMON_HEADERS,
        body: JSON.stringify(result ?? { success: true }),
      };
    } catch (err: any) {
      console.error('[HTTP Handler Error]:', err);
      const statusCode = err instanceof HttpError ? err.statusCode : 500;
      const message = err.message || 'Internal Server Error';
      return {
        statusCode,
        headers: COMMON_HEADERS,
        body: JSON.stringify({ error: message, statusCode }),
      };
    }
  };
}

export function parseJsonBody(event: APIGatewayProxyEventV2): Record<string, any> {
  if (!event.body) return {};
  try {
    const bodyStr = event.isBase64Encoded ? Buffer.from(event.body, 'base64').toString('utf-8') : event.body;
    return JSON.parse(bodyStr);
  } catch {
    throw new ValidationError('Invalid JSON body');
  }
}

export function extractJwtClaims(event: APIGatewayProxyEventV2): Record<string, any> {
  const authorizer = (event.requestContext as any)?.authorizer;
  if (authorizer?.jwt?.claims) {
    return authorizer.jwt.claims;
  }
  if (authorizer?.lambda) {
    return authorizer.lambda;
  }
  const authHeader = event.headers?.authorization || event.headers?.Authorization;
  if (authHeader?.startsWith('Bearer ')) {
    const token = authHeader.split(' ')[1];
    const parts = token.split('.');
    if (parts.length === 3) {
      try {
        const payload = Buffer.from(parts[1], 'base64').toString('utf-8');
        return JSON.parse(payload);
      } catch {
        // Fallthrough to empty
      }
    }
  }
  return {};
}

/**
 * Normalises a groups value that may arrive in several forms:
 *  - A real JS array:  ["admins"]          (from raw JWT decode)
 *  - A serialised array string: "[admins]"  (API GW HTTP JWT authorizer)
 *  - A plain string:   "admins"
 */
function normaliseGroups(raw: unknown): string[] {
  if (Array.isArray(raw)) return raw.map(String);
  if (typeof raw !== 'string') return [];
  const trimmed = raw.trim();
  // API Gateway serialises Cognito array claims as "[val1, val2, ...]"
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    return trimmed
      .slice(1, -1)
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean);
  }
  return [trimmed];
}

export function assertAdmin(event: APIGatewayProxyEventV2): string {
  const claims = extractJwtClaims(event);
  const rawGroups = claims['cognito:groups'] || claims.groups;
  const groupsArray = normaliseGroups(rawGroups);
  const isGroupAdmin = groupsArray.some(
    (g: string) => typeof g === 'string' && ['admin', 'admins'].includes(g.toLowerCase())
  );
  const role = claims['custom:role'] || claims.role;
  const isRoleAdmin = typeof role === 'string' && ['admin', 'admins'].includes(role.toLowerCase());
  if (!isGroupAdmin && !isRoleAdmin) {
    throw new ForbiddenError('Admin access required');
  }
  return claims.sub || claims['cognito:username'] || claims.username || 'admin';
}

import { DynamoDBClient } from '@aws-sdk/client-dynamodb';
import { DynamoDBDocumentClient } from '@aws-sdk/lib-dynamodb';

const client = new DynamoDBClient({
  region: process.env.AWS_REGION || 'eu-central-1',
});

export const ddb = DynamoDBDocumentClient.from(client, {
  marshallOptions: { removeUndefinedValues: true },
});

import { GetCommand, QueryCommand } from '@aws-sdk/lib-dynamodb';
import { ScannerItem } from '../access/types';
import { ConfigItem, DeviceItem, SubscriptionItem, UserItem } from '../types';
import { ddb } from './client';

/** Helper to fetch user profile by user_id */
export async function getUserProfile(tableName: string, userId: string): Promise<UserItem | undefined> {
  const result = await ddb.send(
    new GetCommand({
      TableName: tableName,
      Key: { PK: `USER#${userId}`, SK: 'PROFILE' },
    })
  );
  return result.Item as UserItem | undefined;
}

/** Helper to fetch user's primary subscription */
export async function getUserSubscription(tableName: string, userId: string): Promise<SubscriptionItem | undefined> {
  const result = await ddb.send(
    new QueryCommand({
      TableName: tableName,
      KeyConditionExpression: 'PK = :pk AND begins_with(SK, :sk)',
      ExpressionAttributeValues: {
        ':pk': `USER#${userId}`,
        ':sk': 'SUB#',
      },
    })
  );
  return result.Items?.[0] as SubscriptionItem | undefined;
}

/** Helper to look up active device by API key hash */
export async function getDeviceByApiKey(tableName: string, apiKeyHash: string): Promise<DeviceItem | undefined> {
  const result = await ddb.send(
    new QueryCommand({
      TableName: tableName,
      IndexName: 'ApiKeyIndex',
      KeyConditionExpression: 'api_key_hash = :hash',
      ExpressionAttributeValues: { ':hash': apiKeyHash },
    })
  );
  return result.Items?.[0] as DeviceItem | undefined;
}

/** Helper to look up a registered scanner through the existing API-key index. */
export async function getScannerByApiKey(tableName: string, apiKeyHash: string): Promise<ScannerItem | undefined> {
  const result = await ddb.send(
    new QueryCommand({
      TableName: tableName,
      IndexName: 'ApiKeyIndex',
      KeyConditionExpression: 'api_key_hash = :hash',
      ExpressionAttributeValues: { ':hash': apiKeyHash },
    })
  );
  const scanner = result.Items?.find((item) => String(item.SK).startsWith('SCANNER#')) as ScannerItem | undefined;
  return scanner?.status === 'active' ? scanner : undefined;
}

/** Helper to look up a registered scanner by scanner_id. */
export async function getScannerById(tableName: string, scannerId: string): Promise<ScannerItem | undefined> {
  const result = await ddb.send(
    new QueryCommand({
      TableName: tableName,
      IndexName: 'DeviceIdIndex',
      KeyConditionExpression: 'device_id = :deviceId',
      ExpressionAttributeValues: { ':deviceId': scannerId },
    })
  );
  const scanner = result.Items?.find((item) => String(item.SK).startsWith('SCANNER#')) as ScannerItem | undefined;
  return scanner?.status === 'active' ? scanner : undefined;
}

/** Helper to get config item by key */
export async function getConfigItem(tableName: string, configKey: string): Promise<string | undefined> {
  const result = await ddb.send(
    new GetCommand({
      TableName: tableName,
      Key: { PK: `CONFIG#${configKey}`, SK: 'CONFIG' },
    })
  );
  return (result.Item as ConfigItem | undefined)?.value;
}

export function getMainTableName(): string {
  const name = process.env.MAIN_TABLE_NAME;
  if (!name) throw new Error('MAIN_TABLE_NAME environment variable is required');
  return name;
}

export function getEntryLogsTableName(): string {
  const name = process.env.ENTRY_LOGS_TABLE_NAME;
  if (!name) throw new Error('ENTRY_LOGS_TABLE_NAME environment variable is required');
  return name;
}

export function getAuditLogsTableName(): string {
  const name = process.env.AUDIT_LOGS_TABLE_NAME;
  if (!name) throw new Error('AUDIT_LOGS_TABLE_NAME environment variable is required');
  return name;
}

export function getUserPoolId(): string {
  const id = process.env.USER_POOL_ID;
  if (!id) throw new Error('USER_POOL_ID environment variable is required');
  return id;
}

export function getUserPoolClientId(): string {
  const id = process.env.USER_POOL_CLIENT_ID;
  if (!id) throw new Error('USER_POOL_CLIENT_ID environment variable is required');
  return id;
}

export function getStripeSecretKey(): string {
  const key = process.env.STRIPE_TEST_SECRET_KEY || process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_TEST_SECRET_KEY or STRIPE_SECRET_KEY environment variable is required');
  return key;
}

export function getStripeWebhookSecret(): string {
  const secret = process.env.STRIPE_WEBHOOK_SECRET;
  if (!secret) throw new Error('STRIPE_WEBHOOK_SECRET environment variable is required');
  return secret;
}

export function getStripeSecretKeySsmPath(): string {
  return process.env.STRIPE_SECRET_KEY_SSM_PATH || '/crossbox/stripe/secret_key';
}

export function getStripeWebhookSecretSsmPath(): string {
  return process.env.STRIPE_WEBHOOK_SECRET_SSM_PATH || '/crossbox/stripe/webhook_secret';
}

export function getPaymentProvider(): string {
